(() => {
  const $ = (sel, el=document) => el.querySelector(sel);

  const inp = $('#inp');
  const go = $('#go');
  const rand = $('#rand');
  const strip = $('#strip');
  const poly = $('#poly');

  const normEl = $('#norm');
  const suggEl = $('#sugg');
  const ruleEl = $('#rule');

  const full = $('#full');
  const contractBtn = $('#contract');
  const contrOut = $('#contrOut');
  const contrNote = $('#contrNote');

  // --- Utilities ---
  const tonosMap = {
    'ά':'α','έ':'ε','ή':'η','ί':'ι','ό':'ο','ύ':'υ','ώ':'ω',
    'Ά':'Α','Έ':'Ε','Ή':'Η','Ί':'Ι','Ό':'Ο','Ύ':'Υ','Ώ':'Ω',
    'ΐ':'ι','ΰ':'υ','ϊ':'ι','ϋ':'υ',
    'Ϊ':'Ι','Ϋ':'Υ'
  };

  function stripDiacritics(s){
    // Remove combining marks; also normalize monotonic precomposed tonos.
    let t = s.replace(/[άέήίόύώΆΈΉΊΌΎΏΐΰϊϋΪΫ]/g, ch => tonosMap[ch] || ch);
    // NFD strip combining marks (polytonic too)
    return t.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  }

  function normalizeGreek(s){
    return s
      .replace(/\s+/g,' ')
      .trim();
  }

  function lastIndexOfAny(s, chars){
    for(let i=s.length-1;i>=0;i--) if(chars.includes(s[i])) return i;
    return -1;
  }

  function applyAccentToEta(word, accentType, polytonic=true){
    // Put accent on the final eta of -ης (or -ησ) if present.
    // accentType: 'acute' | 'circ'
    const w = word;
    const lower = w;
    // find final eta before final sigma
    const i = lower.lastIndexOf('η');
    if(i === -1) return word;
    const next = lower[i+1] || '';
    if(next !== 'ς' && next !== 'σ') return word;

    const eta = w[i];
    const isUpper = eta === 'Η';

    if(!polytonic){
      // monotonic: only acute
      const rep = isUpper ? 'Ή' : 'ή';
      return w.slice(0,i) + rep + w.slice(i+1);
    }

    if(accentType === 'circ'){
      const rep = isUpper ? 'ῆ'.toUpperCase() : 'ῆ';
      // JS uppercasing of ῆ gives ῆ; handle explicitly
      const rep2 = isUpper ? 'ῆ'.replace('ῆ','ῆ') : 'ῆ';
      // Better: use precomposed capital eta with perispomeni doesn't exist in Unicode as single char.
      // We'll keep capital Η and add combining perispomeni.
      if(isUpper){
        const comb = 'Η' + '\u0342'; // combining Greek perispomeni
        return w.slice(0,i) + comb + w.slice(i+1);
      }
      return w.slice(0,i) + 'ῆ' + w.slice(i+1);
    } else {
      // acute
      if(isUpper){
        return w.slice(0,i) + 'Ή' + w.slice(i+1);
      }
      return w.slice(0,i) + 'ή' + w.slice(i+1);
    }
  }

  function endsWithEither(s, arr){
    return arr.some(x => s.endsWith(x));
  }

  // --- Example lists from the passage (small, not exhaustive) ---
  const examples = [
    {w:'ψευδής', tag:'adj → acute'},
    {w:'πρηνής', tag:'adj → acute'},
    {w:'ζαής', tag:'adj → acute'},
    {w:'ἁλής', tag:'adj → acute'},
    {w:'σαφής', tag:'adj → acute'},
    {w:'νωθής', tag:'adj → acute'},
    {w:'πλήρης', tag:'special'},
    {w:'Μυῆς', tag:'name (υ-penult) → circ'},
    {w:'Θυῆς', tag:'name (υ-penult) → circ'},
    {w:'Κυῆς', tag:'name (υ-penult) → circ'},
    {w:'Ἡρακλέης', tag:'full form'},
    {w:'Ἡρακλῆς', tag:'contracted → circ'},
    {w:'εὐκλεής', tag:'from κλέος → acute'},
    {w:'δυσκλεής', tag:'from κλέος → acute'},
    {w:'τιμῆς', tag:'from -ηεις → circ'}
  ];

  const knownSpecial = new Map([
    ['πληρης', {out:'πλήρης', rule:'Exception noted by Herodian: πλήρης (from πλειήρης) is not treated like the acute adjectives.'}],
    ['αρης', {out:'Ἄρης', rule:'Proper name: Ἄρης (listed separately).'}]
  ]);

  const knownCircNames = new Set(['ερμης','θαλης','πυλης','ποδης','φαλης','κισσης','σωσης','ηρακλης','σωκλης','προκλης','σοφοκλης','αρτεμης','απελλης']);

  function guessRule(raw){
    const wantPoly = poly.checked;
    const doStrip = strip.checked;

    let s = normalizeGreek(raw);
    if(!s) return {norm:'', out:'', rule:'Type something.'};

    const shownNorm = doStrip ? stripDiacritics(s) : s;
    const base = stripDiacritics(s).toLowerCase();

    // Special known items
    if(knownSpecial.has(base)){
      const k = knownSpecial.get(base);
      return {norm: shownNorm, out: k.out, rule: k.rule};
    }

    // If full form -εης/-εας (bonus) -> contract
    if(endsWithEither(base, ['εης','εας'])){
      const contracted = contractForm(shownNorm, wantPoly);
      const note = base.endsWith('εης')
        ? 'Full form in -έης → contracted proper name in -ῆς (Herodian: Ἡρακλέης → Ἡρακλῆς).'
        : 'Bonus: -έας → -ῆς (Herodian compares Ἀρτεμέας → Ἀρτεμῆς, etc.).';
      return {norm: shownNorm, out: contracted, rule: note};
    }

    // If ends in -ης
    if(!endsWithEither(base, ['ης'])){
      return {norm: shownNorm, out: shownNorm, rule:'This toy focuses on words ending in -ης (or fuller -έης/-έας).'};
    }

    // Heuristic 1: disyllabic proper names with υ in penult: _υης (e.g. Μυης)
    // We'll detect pattern: starts with one consonant cluster + υ + ης and total vowel count ~2.
    if(base.includes('υη') && base.endsWith('ης')){
      // If looks like *-υης and short (<=4 letters excluding final sigma?)
      const core = base.slice(0,-2);
      if(core.endsWith('υ')){
        const out = applyAccentToEta(shownNorm, 'circ', wantPoly);
        return {norm: shownNorm, out, rule:'Heuristic: disyllabic proper name with υ in the penult → circumflex (Μυῆς, Θυῆς, Κυῆς).'};
      }
    }

    // Heuristic 2: known contracted proper names in -ῆς
    if(knownCircNames.has(base)){
      const out = applyAccentToEta(shownNorm, 'circ', wantPoly);
      return {norm: shownNorm, out, rule:'Known proper name pattern from Herodian’s list → circumflex (e.g. Ἑρμῆς, Θαλῆς, Ἡρακλῆς).'};
    }

    // Heuristic 3: from κλέος adjectives: -κλεης (eu/du/akleēs)
    if(base.endsWith('κλεης')){
      const out = applyAccentToEta(shownNorm, 'acute', wantPoly);
      return {norm: shownNorm, out, rule:'Heuristic: adjective from κλέος (…κλεής) → acute (εὐκλεής, ἀκλεής, δυσκλεής).'};
    }

    // Heuristic 4: compounds with ἄω: -αης (akraēs, dysaēs, hyperaēs)
    if(base.endsWith('αης')){
      const out = applyAccentToEta(shownNorm, 'acute', wantPoly);
      return {norm: shownNorm, out, rule:'Heuristic: compound with ἄω ending in -αής → acute (ἀκραής, δυσαής, ὑπεραής).'};
    }

    // Heuristic 5: from -ηεις -> -ῆς (timēs etc.)
    // We can’t derive, but if ends with -μης/-νης/-γης etc. and looks like abstract? We'll just catch τιμης.
    if(base === 'τιμης'){
      const out = applyAccentToEta(shownNorm, 'circ', wantPoly);
      return {norm: shownNorm, out, rule:'Example from Herodian: τιμῆς (as from τιμήεις) → circumflex.'};
    }

    // Default: treat as adjective disyllable in -ης -> acute
    const out = applyAccentToEta(shownNorm, 'acute', wantPoly);
    return {norm: shownNorm, out, rule:'Default toy rule: disyllabic adjectival -ης → acute on the ending (ψευδής-type).'};
  }

  function contractForm(raw, wantPoly){
    let s = normalizeGreek(raw);
    if(strip.checked) s = stripDiacritics(s);
    const base = stripDiacritics(s);

    if(base.toLowerCase().endsWith('εης')){
      // Replace final εης with ῆς (or ής in monotonic)
      const stem = s.slice(0, s.length-3);
      const ending = wantPoly ? 'ῆς' : 'ής';
      return stem + ending;
    }
    if(base.toLowerCase().endsWith('εας')){
      const stem = s.slice(0, s.length-3);
      const ending = wantPoly ? 'ῆς' : 'ής';
      return stem + ending;
    }
    return s;
  }

  function render(res){
    normEl.textContent = res.norm || '—';
    suggEl.textContent = res.out || '—';
    ruleEl.textContent = res.rule || '—';
  }

  function analyze(){
    render(guessRule(inp.value));
  }

  go.addEventListener('click', analyze);
  inp.addEventListener('keydown', (e) => {
    if(e.key === 'Enter') analyze();
  });

  rand.addEventListener('click', () => {
    const ex = examples[Math.floor(Math.random()*examples.length)];
    inp.value = ex.w;
    analyze();
  });

  // Contractor
  contractBtn.addEventListener('click', () => {
    const raw = full.value;
    const s = normalizeGreek(raw);
    if(!s){
      contrOut.textContent = '—';
      contrNote.textContent = 'Type a fuller form ending in -εης or -εας.';
      return;
    }
    const base = stripDiacritics(s).toLowerCase();
    const out = contractForm(s, poly.checked);
    contrOut.textContent = out;

    if(base.endsWith('εης')){
      contrNote.innerHTML = 'Contracted <span class="noteGood">-έης → -ῆς</span> (toy contraction). Try analyzing the result too.';
    } else if(base.endsWith('εας')){
      contrNote.innerHTML = 'Bonus contraction <span class="noteGood">-έας → -ῆς</span> (Herodian compares these).';
    } else {
      contrNote.innerHTML = 'No contraction applied. (This box looks for endings <b>-εης</b> or <b>-εας</b>.)';
    }
  });

  // Example chips
  const chips = $('#chips');
  examples.forEach(ex => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'chip';
    b.textContent = ex.w;
    b.title = ex.tag;
    b.addEventListener('click', () => {
      inp.value = ex.w;
      analyze();
    });
    chips.appendChild(b);
  });

  // Initial state
  inp.value = 'ψευδης';
  analyze();
})();

